#!/usr/bin/env python3
"""Embed the editable factory profile JSON files in firmware."""

import argparse
from pathlib import Path


def build(source: Path, output: Path) -> None:
    profiles = sorted(source.glob("*.json"))
    if not profiles:
        raise SystemExit("No factory profiles found")
    lines = [
        "// Generated by scripts/profiles-to-header.py. Do not edit by hand.",
        "#pragma once",
        "#include <Arduino.h>",
        "struct FactoryProfile { const char* id; const char* json; };",
    ]
    for index, profile in enumerate(profiles):
        raw = profile.read_bytes()
        lines.append(f"static const char factory_profile_{index}[] PROGMEM =")
        for offset in range(0, len(raw), 80):
            chunk = raw[offset : offset + 80]
            escaped = ''.join(f'\\x{byte:02x}' for byte in chunk)
            lines.append(f'  "{escaped}"')
        lines.append(";")
    lines.append("static const FactoryProfile factoryProfiles[] = {")
    for index, profile in enumerate(profiles):
        lines.append(f'  {{"{profile.stem}", factory_profile_{index}}},')
    lines.extend([
        "};",
        "static constexpr size_t factoryProfileCount = sizeof(factoryProfiles) / sizeof(factoryProfiles[0]);",
    ])
    content = "\n".join(lines) + "\n"
    output.parent.mkdir(parents=True, exist_ok=True)
    if not output.exists() or output.read_text() != content:
        output.write_text(content)
    print(f"Embedded {len(profiles)} factory profiles")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("-o", "--output", type=Path, required=True)
    args = parser.parse_args()
    build(args.source, args.output)
